```tsx
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail?: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({
  title,
  detail,
  minutes,
  done,
  onToggle,
}: ChecklistItemProps) {
  return (
    <button
      type="button"
      className={done ? "checklist-item checklist-item--done" : "checklist-item"}
      aria-pressed={done}
      onClick={onToggle}
    >
      <span className="checklist-item__check" aria-hidden="true" />
      <span className="checklist-item__body">
        <span className="checklist-item__title">{title}</span>
        {detail ? <span className="checklist-item__detail">{detail}</span> : null}
      </span>
      <span className="checklist-item__duration">{minutes} min</span>
    </button>
  );
}
```

