:root {
  --myelin-text: #1f2633;
  --myelin-text-muted: #6b7384;
  --myelin-text-faint: #8a92a3;
  --myelin-accent: #2f6f5e;
  --myelin-on-accent: #ffffff;
  --myelin-ring: #2f6f5e;
  --myelin-hover: rgba(31, 38, 51, 0.05);
  --myelin-border: #c9ced8;
}

:root[data-theme="night"] {
  --myelin-text: #e4e8ef;
