  --myelin-on-accent: #0f1714;
  --myelin-ring: #9fd9c6;
  --myelin-hover: rgba(228, 232, 239, 0.06);
  --myelin-border: #3a4252;
}

.checklist-item {
  all: unset;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 0.875rem;
  width: 100%;
  min-height: 2.75rem;
  padding: 0.75rem 0.875rem;
  border-radius: 0.625rem;
  cursor: pointer;
  color: var(--myelin-text);
  font-family: inherit;
  transition: background-color 150ms ease;
}

.checklist-item:hover {
  background-color: var(--myelin-hover);
}

.checklist-item:focus-visible {
  outline: 2px solid var(--myelin-ring);
  outline-offset: 2px;
}

.checklist-item__check {
  position: relative;
  flex-shrink: 0;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  border: 2px solid var(--myelin-border);
  background-color: transparent;
  transition:
    background-color 150ms ease,
    border-color 150ms ease;
}

.checklist-item__check::after {
  content: "";
  position: absolute;
  top: 45%;
  left: 50%;
  width: 0.35rem;
  height: 0.7rem;
  border-style: solid;
  border-color: var(--myelin-on-accent);
  border-width: 0 2px 2px 0;
  transform: translate(-50%, -50%) rotate(45deg);
  opacity: 0;
  transition: opacity 150ms ease;
}

.checklist-item--done .checklist-item__check {
  background-color: var(--myelin-accent);
  border-color: var(--myelin-accent);
}

.checklist-item--done .checklist-item__check::after {
  opacity: 1;
}

.checklist-item__body {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  min-width: 0;
}

.checklist-item__title {
  font-size: 1rem;
  line-height: 1.35;
  font-weight: 500;
  color: var(--myelin-text);
  transition: color 150ms ease;
}

.checklist-item__detail {
  font-size: 0.8125rem;
  line-height: 1.4;
  color: var(--myelin-text-muted);
}

.checklist-item__duration {
  font-size: 0.8125rem;
  color: var(--myelin-text-faint);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.checklist-item--done .checklist-item__title {
  color: var(--myelin-text-muted);
  font-weight: 400;
}

.checklist-item--done .checklist-item__detail,
.checklist-item--done .checklist-item__duration {
  color: var(--myelin-text-faint);
}

@media (prefers-reduced-motion: reduce) {
  .checklist-item,
  .checklist-item__check,
  .checklist-item__check::after,
  .checklist-item__title {
    transition: none;
  }
}
